{
  "subject": "Problema con facturación",
  "message": "No puedo generar facturas desde ayer...",
  "contactEmail": "contacto@email.com"
}

{
  "availability": {
    "scope": "clinic",
    "weekly": [
      {
        "dayOfWeek": 1,
        "isOpen": true,
        "startTime": "09:00",
        "endTime": "18:00"
      }
    ],
    "breaks": [
      {
        "name": "Almuerzo",
        "daysOfWeek": [
          1,
          2,
          3,
          4,
          5
        ],
        "startTime": "13:00",
        "endTime": "14:00"
      }
    ],
    "specialDates": [
      {
        "date": "2026-09-25",
        "isClosed": true,
        "reason": "Feriado",
        "startTime": "10:00",
        "endTime": "14:00"
      }
    ]
  },
  "scheduling": {
    "defaultDurationMin": 30,
    "slotIntervalMin": 15,
    "bufferBetweenAppointmentsMin": 10
  },
  "reminders": {
    "enabled": true,
    "channels": [
      "whatsapp",
      "email"
    ],
    "noticesBeforeMinutes": [
      1440,
      120
    ],
    "messageTemplate": "Hola, {nombre}. Te recordamos tu cita de {tipo} el {fecha} a las {hora}."
  },
  "confirmation": {
    "enabled": true,
    "requestBeforeMinutes": 1440,
    "responseDeadlineBeforeMinutes": 120,
    "channel": "email",
    "noResponseAction": "keep_pending",
    "messageTemplate": "Hola, {nombre}. ¿Confirmas tu cita de {tipo} para el {fecha} a las {hora}?"
  },
  "bookingRules": {
    "patientBookingEnabled": true,
    "minNoticeMinutes": 120,
    "maxAdvanceDays": 60,
    "maxActiveAppointmentsPerPatient": 3,
    "approvalMode": "automatic"
  },
  "changeRules": {
    "cancellation": {
      "enabled": true,
      "minNoticeMinutes": 1440
    },
    "reschedule": {
      "enabled": true,
      "minNoticeMinutes": 1440,
      "maxChangesPerAppointment": 2
    },
    "outOfWindowAction": "contact_clinic",
    "notifyProfessional": true
  }
}
